#define MOD 1000000007

long long comb[1005][1005];

int main() {
    int N, K, S, T;
    scanf("%d %d %d %d", &N, &K, &S, &T);

    int A[N];
    int valid[N];
    int valid_count = 0;

    for (int i = 0; i < N; i++) {
        scanf("%d", &A[i]);
        if ((A[i] & S) == S && (A[i] | T) == T) {
            valid[valid_count++] = A[i];
        }
    }

    // Precompute combinations modulo MOD
    for (int i = 0; i <= N; i++) {
        comb[i][0] = comb[i][i] = 1;
        for (int j = 1; j < i; j++) {
            comb[i][j] = (comb[i-1][j-1] + comb[i-1][j]) % MOD;
        }
    }

    // If S == T
    if (S == T) {
        long long ans = 0;
        for (int i = 1; i <= K && i <= valid_count; i++) {
            ans = (ans + comb[valid_count][i]) % MOD;
        }
        printf("%lld\n", ans);
        return 0;
    }

    // Separate into groups based on bits where S=0 and T=1
    int must_have_one = T & ~S; // bits where 1 must appear at least once
    int must_have_zero = T & ~S; // same set, but we need both 0 and 1

    int only_one = 0, only_zero = 0, both = 0;
    for (int i = 0; i < valid_count; i++) {
        int has_one = (valid[i] & must_have_one) == must_have_one;
        int has_zero = (valid[i] & must_have_one) == 0;
        if (has_one && has_zero) both++;
        else if (has_one) only_one++;
        else if (has_zero) only_zero++;
    }

    long long ans = 0;
    // At least 2 numbers must be chosen, because S != T
    for (int size = 2; size <= K && size <= valid_count; size++) {
        // choose at least one from only_one and at least one from only_zero
        for (int a = 1; a <= only_one && a <= size - 1; a++) {
            for (int b = 1; b <= only_zero && a + b <= size; b++) {
                int c = size - a - b;
                if (c < 0 || c > both) continue;
                long long ways = (comb[only_one][a] * comb[only_zero][b]) % MOD;
                ways = (ways * comb[both][c]) % MOD;
                ans = (ans + ways) % MOD;
            }
        }
    }

    printf("%lld\n", ans);
    return 0;
}

