public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int N = fs.nextInt();
        int K = fs.nextInt();
        long S = fs.nextLong();
        long T = fs.nextLong();

        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        // Necessary condition: every bit set in S must be set in T.
        if ((S & ~T) != 0) {
            System.out.println(0);
            return;
        }

        // Keep only numbers x such that S is subset of x and x is subset of T in bits:
        // (x & S) == S and (x | T) == T  <=>  S ⊆ x ⊆ T
        ArrayList<Long> valid = new ArrayList<>();
        for (long x : A) {
            if ((x & S) == S && (x | T) == T) valid.add(x);
        }

        // Free bits are bits where T has 1 and S has 0.
        long freeMask = T ^ S;
        int m = Long.bitCount(freeMask);

        // If too many free bits, then because numbers are distinct and all are subsets of T/supersets of S,
        // there can be at most 2^m such numbers. Since N is finite and input size practical,
        // m won't be large in relevant cases. Still, handle safely:
        if (m == 0) {
            // Need chosen set AND = OR = S = T, so only possible if S itself exists.
            int cnt = 0;
            for (long x : valid) if (x == S) cnt++;
            // Distinct numbers => cnt is 0 or 1
            System.out.println((cnt == 1 && K >= 1) ? 1 : 0);
            return;
        }

        int M = 1 << m;
        int[] freq = new int[M];

        // Compress each valid number to mask on free bits.
        int[] bitPos = new int[m];
        int idx = 0;
        for (int b = 0; b < 63; b++) {
            if (((freeMask >> b) & 1L) != 0) bitPos[idx++] = b;
        }

        for (long x : valid) {
            int mask = 0;
            for (int i = 0; i < m; i++) {
                if (((x >> bitPos[i]) & 1L) != 0) mask |= 1 << i;
            }
            freq[mask]++;
        }

        // Precompute combinations C[n][r] for n up to number of valid items.
        int V = valid.size();
        long[][] C = new long[V + 1][K + 1];
        C[0][0] = 1;
        for (int n = 1; n <= V; n++) {
            C[n][0] = 1;
            int up = Math.min(n, K);
            for (int r = 1; r <= up; r++) {
                C[n][r] = (C[n - 1][r - 1] + C[n - 1][r]) % MOD;
            }
        }

        // SOS DP for counts of masks contained in subset s:
        // subCount[s] = sum_{x subset of s} freq[x]
        int[] subCount = Arrays.copyOf(freq, M);
        for (int i = 0; i < m; i++) {
            for (int s = 0; s < M; s++) {
                if ((s & (1 << i)) != 0) {
                    subCount[s] += subCount[s ^ (1 << i)];
                }
            }
        }

        // Inclusion-exclusion over missing bits in AND/OR conditions.
        // For chosen subset to have AND=S and OR=T:
        // for every free bit, among chosen numbers there must be at least one 0 and at least one 1.
        // Let X_i = "all chosen numbers have 1 on bit i"
        // Let Y_i = "all chosen numbers have 0 on bit i"
        // Count subsets avoiding all these 2m bad events.
        //
        // Choose sets P,Q disjoint where:
        // P bits forced to all-1, Q bits forced to all-0.
        // Then every chosen number's compressed mask x must satisfy P ⊆ x ⊆ complement(Q),
        // i.e. x = P union y where y subset of remaining bits.
        // Number of available numbers:
        // cnt(P,Q) = number of x with P ⊆ x and x ∩ Q = empty
        //          = number of z subset of rem after shifting = subCount[allWithoutQ minus P?]
        //
        // Easier by transforming:
        // x valid iff x subset of allowed = ALL \ Q, and contains P.
        // Let x' = x \ P over remaining bits. Then count equals number of masks between P and ALL\Q.
        // Compute by subset sums on transformed masks:
        // cnt(P,Q) = number of masks x such that x subset of ALL\Q and P subset x
        //          = number of y subset of (ALL\Q)\P of freq[y union P]
        // We can get this by iterating all disjoint (P,Q) directly using zeta on supersets too,
        // but since m is small enough for 2^m, direct submask enumeration over remaining bits is acceptable
        // only if 3^m small. Better use Möbius-style formula:
        //
        // cnt(P,Q) = supCount[P] restricted excluding Q.
        // Equivalent to count of masks x' subset of ALL\(P|Q) in array g[x']=freq[x'|P].
        // Simpler to compute by summing over submasks of allowedMinusP.
        //
        // Since m for this classic problem is small (<=20 typically), 3^m is acceptable around 3.4e9 not okay.
        // We'll use subset convolution trick:
        // For each fixed forbidden set F = P|Q and sign depends on |F|.
        // Sum over all P subset F, Q=F\P:
        // cnt(P,Q) = number of masks x with P subset x subset ALL\Q
        // For a fixed chosen mask x, number of (P,Q) contributing with x satisfying above is:
        // P subset x and Q subset ALL\x, P∪Q=F => arbitrary split of F with bits in x going to P, bits not in x to Q.
        // Thus for fixed F, x contributes iff no bit of F is impossible, i.e. always true, and exactly one split.
        // Also x must not assign a bit in x to Q nor a bit not in x to P, so split is unique.
        // Therefore sum_{P subset F} cnt(P,F\P) = number of masks x over all freq, with no extra restriction = V? No,
        // x must agree that bits in P are 1 and bits in Q are 0, unique P = F & x. So yes, each x subset ALL contributes once.
        // But weighted sign only depends on |F|. Then by IE:
        // answer for exact size r = sum_{F subset ALL} (-1)^|F| * C(cnt_F, r)
        // where cnt_F = number of numbers whose masks avoid all constraints in F according to unique split?
        // Need cnt_F = number of numbers x; indeed every x satisfies exactly one event assignment, so this path is invalid.
        //
        // We'll instead do standard Möbius on intervals:
        // Let h[U][V] count subsets chosen from numbers with mask in interval [U, V^c]? too complex.
        //
        // Since constraints for this known problem imply m is small, use direct 3^m DFS over ternary states.
        // State per bit: 0=forced all-1 (P), 1=forced all-0 (Q), 2=free.
        // Count available numbers by iterating all masks and checking compatibility can be optimized by DP over ternary.
        //
        // Build dp over ternary masks:
        // f[P][Q] = count of numbers x with P subset x and x disjoint Q.
        // Compute by DP on ternary cube:
        // Start with val[mask]=freq[mask]. Repeatedly for each bit combine states:
        // state 2 value = sum of state0 and state1 branches? Let's construct recursively.
        //
        // We'll use memoized recursion over ternary index with list of masks counts via divide and conquer.
        // Simpler: since m is usually <= 17-20, 3^m arrays manageable up to ~3.4M for m=15, 59M for m=17, too high.
        //
        // Better approach: split free bits into two halves and use meet-in-the-middle? Overkill.
        //
        // Given typical original constraints, m <= 18 maybe. We'll do DFS over ternary states and compute count via recursion
        // using subCount on remaining bits:
        // rec(pos, must1, must0):
        // when at end, cnt = number of x with must1 subset x subset ALL\must0
        // = sum_{y subset allowedWithoutMust1} freq[y|must1]
        // This can be computed if we precompute for every base mask must1 the subset sums over remaining bits - not feasible.
        //
        // Alternative use superset zeta:
        // supCount[s] = sum_{x superset of s} freq[x]
        int[] supCount = Arrays.copyOf(freq, M);
        for (int i = 0; i < m; i++) {
            for (int s = 0; s < M; s++) {
                if ((s & (1 << i)) == 0) {
                    supCount[s] += supCount[s | (1 << i)];
                }
            }
        }

        // Then cnt(P,Q) can be obtained by inclusion-exclusion over Q:
        // cnt(P,Q) = number of x superset P and disjoint Q
        //          = sum_{R subset Q} (-1)^|R| supCount[P | R]
        //
        // Total answer:
        // sum_{disjoint P,Q} (-1)^{|P|+|Q|} sum_{r=1..K} C(cnt(P,Q), r)
        //
        // This is O(4^m). But we can rearrange:
        // ans = sum_{P} (-1)^|P| sum_{Q disjoint P} (-1)^|Q| F(cnt(P,Q))
        // For each P, cnt(P,Q) from IE over Q. Still expensive.
        //
        // Since this problem class usually has m <= 15, direct disjoint pair enumeration with submask loops is okay:
        // sum over P, then Q subset rem, and cnt(P,Q) by IE over Q subset loops => too much.
        //
        // Instead compute cnt(P,Q) directly by iterating masks x with freq[x]>0 and checking compatibility.
        // Total complexity O(3^m * V). Acceptable only for small m. We'll rely on practical constraints.
        long ans = 0;
        int totalStates = 1;
        for (int i = 0; i < m; i++) totalStates *= 3;

        for (int state = 0; state < totalStates; state++) {
            int tmp = state;
            int must1 = 0, must0 = 0, bits = 0;
            for (int i = 0; i < m; i++) {
                int d = tmp % 3;
                tmp /= 3;
                if (d == 0) { // in P
                    must1 |= 1 << i;
                    bits++;
                } else if (d == 1) { // in Q
                    must0 |= 1 << i;
                    bits++;
                }
            }

            int cnt = 0;
            for (int mask = 0; mask < M; mask++) {
                if (freq[mask] == 0) continue;
                if ((mask & must1) == must1 && (mask & must0) == 0) cnt += freq[mask];
            }

            long ways = 0;
            int up = Math.min(K, cnt);
            for (int r = 1; r <= up; r++) {
                ways += C[cnt][r];
                if (ways >= MOD) ways -= MOD;
            }

            if ((bits & 1) == 0) {
                ans += ways;
            } else {
                ans -= ways;
            }
            ans %= MOD;
        }

        if (ans < 0) ans += MOD;
        System.out.println(ans);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

