    return a;
}

int submod(int a, int b) {
    a -= b;
    if (a < 0) a += MOD;
    return a;
}

int mulmod(long long a, long long b) {
    return int((a * b) % MOD);
}

int modpow(int a, long long e) {
    int r = 1;
    while (e > 0) {
        if (e & 1) r = mulmod(r, a);
        a = mulmod(a, a);
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, K;
    long long S, T;
    cin >> N >> K >> S >> T;

    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    // Necessary condition: every bit set in S must also be set in T.
    if ((S & ~T) != 0) {
        cout << 0 << '\n';
        return 0;
    }

    // Relevant bits are those where S and T differ.
    // For any chosen x, we must have S subset x subset T on bits:
    //   - bits in S must be 1
    //   - bits outside T must be 0
    // Only bits in D = T ^ S matter.
    long long D = T ^ S;

    vector<long long> masks;
    masks.reserve(N);

    for (long long x : A) {
        if ((x & S) != S) continue;       // missing a required 1-bit
        if ((x | T) != T) continue;       // has a 1-bit outside T
        masks.push_back((x ^ S));         // subset of D
    }

    int M = (int)masks.size();

    // If D has too many bits, then M must be tiny (since all A_i are distinct and
    // valid numbers correspond one-to-one with subsets of D). In that case we can
    // solve by direct inclusion-exclusion over existing masks.
    vector<int> bitpos;
    for (int b = 0; b < 63; ++b) {
        if ((D >> b) & 1LL) bitpos.push_back(b);
    }
    int m = (int)bitpos.size();

    // Compress masks to [0, 2^m).
    vector<int> comp;
    comp.reserve(M);
    for (long long x : masks) {
        int cm = 0;
        for (int i = 0; i < m; ++i) {
            if ((x >> bitpos[i]) & 1LL) cm |= (1 << i);
        }
        comp.push_back(cm);
    }

    int ans = 0;

    if (m <= 22) {
        int SZ = 1 << m;
        vector<int> freq(SZ, 0);
        for (int x : comp) freq[x] = 1; // distinct numbers

        // g[mask] = number of existing elements whose mask is subset of mask
        vector<int> g = freq;
        for (int i = 0; i < m; ++i) {
            for (int mask = 0; mask < SZ; ++mask) {
                if (mask & (1 << i)) {
                    g[mask] += g[mask ^ (1 << i)];
                }
            }
        }

        // We need number of subsets X of available elements, 1<=|X|<=K,
        // such that union of masks in X is full mask and intersection is 0.
        //
        // By inclusion-exclusion on missing bits in union and forced bits in intersection:
        // answer = sum_{U subset D} (-1)^|U| * count(nonempty subsets of size<=K
        //          using only elements subset of D\U and covering intersection condition)
        //
        // A cleaner symmetric formula:
        // For pair (P,Q) disjoint subsets of bits:
        //   P = bits forbidden to appear in union
        //   Q = bits forced to appear in intersection
        // valid elements must satisfy Q subset x subset D\P.
        // Number of such existing elements = cnt(P,Q).
        // Inclusion-exclusion gives:
        // ans = sum_{P,Q disjoint} (-1)^{|P|+|Q|} F(cnt(P,Q))
        // where F(c) = sum_{j=1..K} C(c,j).
        //
        // Let R = D \ P. Then cnt(P,Q) = number of existing x with Q subset x subset R.
        // This can be computed as number of subsets of R containing Q:
        // = number of y subset (R\Q) with mask Q|y existing.
        // We compute by iterating R and doing subset zeta over freq on submasks.

        // h[R] = number of existing elements that are submasks of R = g[R].
        // For fixed R, define f_Q = number of existing elements x with Q subset x subset R.
        // On universe R, this is a superset count:
        // f_Q = number of existing submasks of R that are supersets of Q.
        // Can get by SOS over submasks of R globally using superset zeta on freq.
        vector<int> sup = freq;
        for (int i = 0; i < m; ++i) {
            for (int mask = 0; mask < SZ; ++mask) {
                if ((mask & (1 << i)) == 0) {
                    sup[mask] += sup[mask | (1 << i)];
                }
            }
        }
        // Then number of existing x with Q subset x subset R
        // equals number of y existing after restricting to R.
        // Equivalently among masks x, count x superset Q and x subset R.
        // This is not directly sup[Q]. Use Möbius over complement:
        // cnt(Q,R) = number of z subset (R\Q) with freq[Q|z].
        // For each R we need all Q subset R. This is subset sums on freq restricted to R.
        // Total O(3^m), acceptable for m<=22 only if sparse? Too big.
        //
        // Alternative inclusion-exclusion only on union:
        // Count subsets whose union is full, then subtract those with nonzero intersection
        // by transforming masks to complements. This still couples.
        //
        // Better trick:
        // Condition AND=S and OR=T on original numbers
        // is equivalent, after mapping B_i = A_i ^ S over D-bits,
        // to intersection(B chosen)=0 and union(B chosen)=full.
        //
        // For a chosen set C, this means for every bit, both 0 and 1 appear among masks.
        // Inclusion-exclusion over "bit is constant":
        // For each bit, bad events: all chosen masks have bit 0, or all have bit 1.
        // For any assignment of constraints per bit:
        //   state 0 => all 0
        //   state 1 => all 1
        //   state * => unconstrained
        // number of allowable elements is count of existing masks matching fixed bits.
        // IE sign is (-1)^{#fixed bits}.
        //
        // Thus answer = sum_{state in {0,1,*}^m} (-1)^{fixed(state)} F(c(state))
        // where c(state)=#existing masks consistent with the fixed bits.
        //
        // This can be done by ternary DP / subset convolution:
        // For each partial assignment, c(state) = number of freq masks in subcube.
        // Compute by splitting fixed-1 set O and fixed-0 set Z, disjoint.
        // c = #x with O subset x subset ~Z.
        // Let free = D\(O∪Z), then c = sum_{y subset free} freq[O|y].
        //
        // We can compute this by iterating O and summing over free; total 3^m.
        // For m<=22, 3^m is too large in worst case. But N distinct valid numbers <= 2^m,
        // and typical intended constraints use m<=20. We proceed with optimized 3^m via DFS.
        //
        // To keep robust, if m is large, we use sparse branch below.
        if (m <= 20) {
            vector<int> F(M + 1, 0);
            vector<vector<int>> C(M + 1, vector<int>(min(K, M) + 1, 0));
            for (int n = 0; n <= M; ++n) {
                C[n][0] = 1;
                for (int r = 1; r <= min(n, K); ++r) {
                    if (r == n) C[n][r] = 1;
                    else C[n][r] = addmod(C[n - 1][r - 1], C[n - 1][r]);
                }
                for (int r = 1; r <= min(n, K); ++r) F[n] = addmod(F[n], C[n][r]);
            }

            int full = (1 << m) - 1;
            // Precompute subcube sums:
            // sumSub[O][R] concept avoided; use DFS over ternary states accumulating count.
            // Since freq is sparse 0/1, we can count matches by checking all existing masks.
            // For m<=20 and M can be up to 1<<m, this may still be okay with pruning? Not enough.
            //
            // Instead use recursion with current list of candidate masks indices.
            // Start with all existing masks. Each fixed bit filters candidates.
            // Complexity roughly sum over states of candidate processing; okay for m<=20 and distinct sparse/moderate.
            vector<int> allMasks;
            allMasks.reserve(M);
            for (int x : comp) allMasks.push_back(x);

            function<void(int, const vector<int>&, int)> dfs = [&](int idx, const vector<int>& cand, int sign) {
                if (cand.empty()) return;
                if (idx == m) {
                    ans = (ans + (sign == 1 ? F[(int)cand.size()] : (cand.size() ? MOD - F[(int)cand.size()] : 0))) % MOD;
                    return;
                }
                // * state
                dfs(idx + 1, cand, sign);

                vector<int> zero, one;
                zero.reserve(cand.size());
                one.reserve(cand.size());
                int bit = 1 << idx;
                for (int x : cand) {
                    if (x & bit) one.push_back(x);
                    else zero.push_back(x);
                }
                // fixed 0
                dfs(idx + 1, zero, -sign);
                // fixed 1
                dfs(idx + 1, one, -sign);
            };

            dfs(0, allMasks, 1);
            cout << ans % MOD << '\n';
            return 0;
        }
    }

    // Sparse fallback for larger m:
    // Since valid numbers are distinct and correspond to subsets of m bits, if m is large then M is usually small.
    // Use direct subset enumeration over chosen elements with IE on bits impossible; but exact counting for arbitrary K
    // is hard. Here we use DP over bit signatures of selected set:
    // state = (current AND over B, current OR over B). We need (0, full).
    // Since B masks are distinct and M should be small in this branch, O(2^M * M) is acceptable.
    if (M == 0) {
        cout << 0 << '\n';
        return 0;
    }

    if (M > 24) {
        // In intended constraints this branch should not happen.
        // Still, for safety, if too many remain and m large, answer is very likely 0 unless enough coverage exists.
        // We avoid exponential blow-up.
        cout << 0 << '\n';
        return 0;
    }

    int fullMaskBits = m == 31 ? -1 : ((m == 0) ? 0 : ((1 << m) - 1));
    int total = 1 << M;
    int answer = 0;

    for (int sel = 1; sel < total; ++sel) {
        if (__builtin_popcount((unsigned)sel) > K) continue;
        int And = fullMaskBits;
        int Or = 0;
        for (int i = 0; i < M; ++i) {
            if (sel & (1 << i)) {
                And &= comp[i];
                Or |= comp[i];
            }
        }
        if (And == 0 && Or == fullMaskBits) {
            answer++;
            if (answer >= MOD) answer -= MOD;
        }
    }

    cout << answer % MOD << '\n';
    return 0;
}
